import React, { Component } from "react";
import { Router,Routes , Route, Link  } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";
import "./App.css";

import AuthService from "./services/auth.service";
 
import Login from "./components/login.component";
import Logout from "./components/Logout";
import Register from "./components/register.component";
import Home from "./components/home.component";
import Profile from "./components/profile.component";
import BoardUser from "./components/board-user.component";
import BoardModerator from "./components/board-moderator.component";
import BoardAdmin from "./components/board-admin.component";
import Cours from "./components/cours.component";
import Calculatrice from "./components/Calculatrice/Calculatrice"
import Compteur from "./services/Compteur"
import jwt_decode from "jwt-decode";

class App extends Component {
  constructor(props) {
    super(props);
    //this.logOut = this.logOut.bind(this);
    this.state = {
      showModeratorBoard: false,
      showAdminBoard: false,
      currentUser: undefined,
    };
  }
  // 
  componentDidMount() {


    // Bis Später 
   //const user = jwt_decode(AuthService.getCurrentUser()).sub;
    const user = AuthService.getCurrentUser();
    document.body.style.backgroundColor = user===null?"#23395d":"#1CD4C";

    if (user!=null) {

      this.setState({
        currentUser: jwt_decode(AuthService.getCurrentUser()).sub,
        showModeratorBoard: jwt_decode(AuthService.getCurrentUser()).roles.includes("check"),
        showAdminBoard: jwt_decode(AuthService.getCurrentUser()).sub.includes("3amel"),
      });
    }
  }
  //
  

  handelLogOut() {
    AuthService.logout().then(() => {
      setTimeout(()=> window.location.replace('http://localhost:8081/tana'),300)});;
    
  }
  render() {

    const { currentUser, showModeratorBoard, showAdminBoard } = this.state;
    return (
      <div>
      
        <nav className="navbar navbar-expand navbar-dark bg-dark">
        <Link to={"/"} className="navbar-brand">
          
          ⴰⵣⵣⵓⵍ
          </Link>

          <div className="navbar-nav mr-auto">
            <li className="nav-item">
              <Link to={"/login"} className="nav-link">
              ⴽⵊⴰⵎ(Login)
              </Link>
            </li>
           
           
            {showModeratorBoard && (
              <li className="nav-item">
                <Link to={"/3aml"} className="nav-link">
                  3amel
                </Link>
              </li>
            )}
            {showAdminBoard && (
              <li className="nav-item">
                <Link to={"/CHekh"} className="nav-link">
                  Admin Board
                </Link>
              </li>
            )}
            
            </div>
          {currentUser ? (
            <div className="navbar-nav ml-auto">
              <li className="nav-item">
                <Link to={"/profile"} className="nav-link">
                  {currentUser}
                </Link>
              </li>
              <li className="nav-item">
              <Link to={"/cours"} className="nav-link">
              ⴰⵍⵎⴰⴷ (Cours)
              </Link>

               </li>
               <li className="nav-item">
              
              <Link to={"/user"} className="nav-link">
              ⵍⵉⵙⵜⴰ(Users)
              </Link>
              </li>
              <li className="nav-item">
              <Link to={"/logout"} className="nav-link" onClick={this.handelLogOut}>
              ⴼⴼⴰⵖ
              </Link>
             </li>
              
            </div>

          ) : (
            <div className="navbar-nav ml-auto">
                         
              <li className="nav-item">
                <Link to={"/register"} className="nav-link">
                ⵙⴰⵊⴰⵍ/registre/تسجيل
                </Link>
              </li>
               <li className="nav-item">
              <a href={"https://nbenoudi.github.io/aghabdil/"} className="nav-link">
              Aghabdil
              </a>
              </li>

              <li className="nav-item">
                <Link to={"/Calculatrice"} className="nav-link">
                ⴰⵙⵙⵉⴷⵏ / Calculatrice
                </Link>
              </li>
              
            </div>
            
          )}
        </nav>
        <div className="container  mt-3">
      
          <Routes >
           <Route exact path={"/ⵙⵙⵉⴷⵏ"} element={<Compteur/>}></Route>  
           <Route exact path={"/Calculatrice"} element={<Calculatrice/>}></Route>
           <Route exact path={"/"} element={<Home/>} /> 
            <Route exact path="/login" element={<Login /> }/>
            <Route exact path="/register" element={<Register />} />
            <Route exact path="/cours" element={<Cours />} />
            <Route exact path="/profile" element={<Profile/>} />
            <Route exact path="/user" element={<BoardUser/>} />
            <Route path="/mod" element={<BoardModerator/>} />
           <Route path="/admin" element={<BoardAdmin/>} />
           <Route path="/logout" element={<Logout/>} />
          
          </Routes >
          
        </div>
      </div>
    );
  }
}


export default App;
